#!/usr/bin/env node
/**
 * Post-process `drizzle-kit pull` output for the site schema.
 *
 * The site's tables live in the `makerslounge` Postgres schema rather than
 * `public`, and drizzle-kit disambiguates non-public tables by suffixing every
 * export: `profiles` becomes `profilesInMakerslounge`. Nothing else in the
 * codebase needs that disambiguation — there is exactly one `profiles` table —
 * and the suffix would show up at every one of the ~100 call sites.
 *
 * So: strip it, prepend the provenance header, and copy the generated files
 * from drizzle/site/ (gitignored) into src/db/site/ (committed).
 *
 * Usage:
 *   DATABASE_URL=... npx drizzle-kit pull --config drizzle.site.config.ts
 *   node scripts/strip-schema-suffix.mjs
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";

const SUFFIX = "InMakerslounge";

const SCHEMA_HEADER = `// Site schema — the tables behind makerslounge.ca, now living in Neon.
//
// GENERATED, do not hand-edit. Produced by \`drizzle-kit pull\` against the live
// Neon \`makerslounge\` schema, which was itself created from a Supabase
// \`pg_dump --schema-only\`.
//
// Regenerate with:
//   DATABASE_URL=... npx drizzle-kit pull --config drizzle.site.config.ts
//   node scripts/strip-schema-suffix.mjs
//
// Generating rather than hand-writing is deliberate: the previous hand-written
// version had drifted from production — it was missing \`profiles.clerk_user_id\`
// (added during the Clerk cutover) and described 25 foreign keys where the
// database has 43. A missing column throws; a missing constraint does not.
//
// No RLS policies here on purpose. Supabase enforced 112 of them in SQL; Neon
// has no JWT-aware policy layer, so authorization is per-route application code
// instead. See docs/supabase-to-clerk-neon-migration.md.

`;

const RELATIONS_HEADER = `// GENERATED by \`drizzle-kit pull\` — Drizzle relations for the site schema.
// See ./schema.ts for provenance and how to regenerate.

`;

const jobs = [
  { from: "drizzle/site/schema.ts", to: "src/db/site/schema.ts", header: SCHEMA_HEADER },
  { from: "drizzle/site/relations.ts", to: "src/db/site/relations.ts", header: RELATIONS_HEADER },
];

let failed = false;
for (const { from, to, header } of jobs) {
  if (!existsSync(from)) {
    console.error(`missing ${from} — run drizzle-kit pull first`);
    failed = true;
    continue;
  }
  let body = readFileSync(from, "utf8").replaceAll(SUFFIX, "");

  // drizzle-kit mis-emits an empty-string column default as `default(')`, which
  // is an unterminated string literal and fails to parse. Only
  // `hackathon_voter_notes.notes` has `DEFAULT ''::text` today, but repair it
  // generically so a new empty-string default doesn't silently break the build.
  const emptyDefault = /\.default\('\)/g;
  const repaired = (body.match(emptyDefault) || []).length;
  if (repaired) {
    body = body.replace(emptyDefault, `.default("")`);
    console.log(`  repaired ${repaired} empty-string default(s)`);
  }

  writeFileSync(to, header + body);
  console.log(`wrote ${to}`);
}
process.exit(failed ? 1 : 0);
